    "* Misaal ke taur par — aapke rates aur prints aapki dukaan par depend karte hain. Upar se time ki bachat aur photo/resume ki extra kamai alag.": "* ఉదాహరణ మాత్రమే — మీ రేట్లు, ప్రింట్ల సంఖ్య మీ దుకాణంపై ఆధారపడతాయి. దీనికి తోడు సమయం ఆదా మరియు ఫోటో/రెజ్యూమే అదనపు ఆదాయం వేరు.",
