    ": if you are charged twice for the same licence, or money is taken and access is never given, send us the transaction ID and the extra amount goes back to the original payment method, usually within 5–7 working days. Money your customers pay you for printing is": ": ఒకే లైసెన్స్‌కు రెండుసార్లు ఛార్జ్ అయినా, లేదా డబ్బు తీసుకుని ప్రవేశం ఇవ్వకపోయినా, లావాదేవీ IDని మాకు పంపండి — అదనపు మొత్తం అసలు చెల్లింపు మార్గానికే తిరిగి వెళ్తుంది, సాధారణంగా 5–7 పని దినాల్లో. ప్రింటింగ్ కోసం మీ కస్టమర్లు మీకు చెల్లించే డబ్బు",
    ": job ID and time, number of pages and copies, colour or black-and-white, the amount paid and payment status, and whether the file was printed and cleared.": ": జాబ్ ID మరియు సమయం, పేజీలు మరియు కాపీల సంఖ్య, రంగు లేదా బ్లాక్-అండ్-వైట్, చెల్లించిన మొత్తం మరియు చెల్లింపు స్థితి, మరియు ఫైల్ ప్రింట్ అయ్యి తొలగిందా అన్నది.",
    "A free demo of the complete software is available on qrseprint.in before you pay anything, so you can test it with your own printer first. What we do guarantee is that your setup gets finished — if you cannot install it, we will install it for you.": "మీరు ఏదైనా చెల్లించే ముందే పూర్తి సాఫ్ట్‌వేర్ ఉచిత డెమో qrseprint.in లో అందుబాటులో ఉంది, కాబట్టి ముందుగా మీ సొంత ప్రింటర్‌తో పరీక్షించుకోవచ్చు. మేము హామీ ఇచ్చేది ఒక్కటే — మీ సెటప్ పూర్తవుతుంది; మీరు ఇన్‌స్టాల్ చేయలేకపోతే మేమే చేసి ఇస్తాము.",
    "A job that is never paid for, or never printed, is cleared automatically as well, so nothing lingers on qrseprint.in indefinitely. Because deletion is immediate,": "చెల్లింపు జరగని లేదా ప్రింట్ కాని జాబ్ కూడా ఆటోమేటిక్‌గా తొలగిపోతుంది, కాబట్టి qrseprint.in లో ఏదీ నిరవధికంగా ఉండదు. తొలగింపు వెంటనే జరుగుతుంది కాబట్టి,",
    "A shop account on qrseprint.in may be opened by any cyber cafe, stationery shop, print shop, or similar business operated by a person aged 18 or above. You must give accurate details when registering and keep your Shop ID and password confidential. Anything done through your account is treated as done by you.": "18 ఏళ్లు పైబడిన వ్యక్తి నడిపే ఏ సైబర్ కేఫ్, స్టేషనరీ షాప్, ప్రింట్ షాప్ లేదా అలాంటి వ్యాపారమైనా qrseprint.in లో షాప్ ఖాతా తెరవవచ్చు. నమోదు సమయంలో సరైన వివరాలు ఇవ్వాలి, మీ షాప్ ID మరియు పాస్‌వర్డ్‌ను గోప్యంగా ఉంచుకోవాలి. మీ ఖాతా ద్వారా జరిగినదంతా మీరే చేసినట్టుగా పరిగణించబడుతుంది.",
    "A3 / A2 / A1 + Duplex": "A3 / A2 / A1 + రెండు వైపులా",
    "API Key": "API కీ",
    "AUTO PRINT": "ఆటో ప్రింట్",
    "Aage Bado →": "ముందుకు సాగండి →",
    "Aage kabhi kaam aayega — abhi download kar lo": "ముందు ముందు ఉపయోగపడుతుంది — ఇప్పుడే డౌన్‌లోడ్ చేసుకోండి",
    "Aaj ke bhi, kal ke bhi. Jo bhi naya advance feature banega, apne aap mil jayega — dobara paisa nahi.": "ఈనాటిదీ, రేపటిదీ. కొత్తగా ఏ అడ్వాన్స్ ఫీచర్ వచ్చినా దానంతట అదే లభిస్తుంది — మళ్లీ డబ్బు లేదు.",
    "Aaj ke saare advance features. Aage koi naya advance feature aaya to ₹49 me alag se": "ఈనాటి అడ్వాన్స్ ఫీచర్లన్నీ. ఇక కొత్త ఫీచర్ ఏదైనా వస్తే ₹49కు విడిగా",
    "Aaj ke saare advance features. Aage naya advance feature aaya to ₹49 me alag se": "ఈనాటి అడ్వాన్స్ ఫీచర్లన్నీ. ఇక కొత్త ఫీచర్ వస్తే ₹49కు విడిగా",
    "Aap counter pe baithe raho — file lena, kholna, print dabana — kuch nahi. Payment ka record khud banta hai.": "మీరు కౌంటర్‌లో కూర్చుంటే చాలు — ఫైల్ తీసుకోవడం, తెరవడం, ప్రింట్ నొక్కడం — ఏదీ అవసరం లేదు. చెల్లింపు రికార్డు దానంతట అదే తయారవుతుంది.",
    "Aap ek customer ka print nikal rahe ho, baaki 5 khade hain. File lo, kholo, print karo — poora din isi me jata hai.": "మీరు ఒక కస్టమర్ ప్రింట్ తీస్తుంటే, మిగతా 5 మంది నిలబడి ఉంటారు. ఫైల్ తీసుకో, తెరువు, ప్రింట్ చేయి — రోజంతా ఇందులోనే గడిచిపోతుంది.",
    "Aapka document print ho raha hai.": "మీ పత్రం ప్రింట్ అవుతోంది.",
    "Aapka kaam: QR chipkao. Bas.": "మీ పని: QR అతికించండి. అంతే.",
