    "Aapka time": "మీ సమయం",
    "Aapke link se jo bhi register kare, wo aapki shop. Panel me sab dikhta rahega.": "మీ లింక్ ద్వారా ఎవరు నమోదు చేసినా అది మీ షాప్. ప్యానెల్‌లో అంతా కనిపిస్తుంది.",
    "Aasan software installation": "సులభమైన సాఫ్ట్‌వేర్ ఇన్‌స్టాలేషన్",
    "Ab QR scan karke phone se test print karo aur payment": "ఇప్పుడు QR స్కాన్ చేసి ఫోన్ నుండి టెస్ట్ ప్రింట్ చేసి చెల్లింపు",
    "Ab aage badh sakte ho": "ఇప్పుడు ముందుకు సాగవచ్చు",
    "Ab apni dukaan ka QR scan karke ek": "ఇప్పుడు మీ దుకాణం QRని స్కాన్ చేసి ఒక",
    "Abhi Start Karein": "ఇప్పుడే ప్రారంభించండి",
    "About": "గురించి",
    "About QR Se Print": "QR Se Print గురించి",
    "About the Creator": "సృష్టికర్త గురించి",
    "About two minutes to register the shop, plus a one-time install of the Windows print agent. After that the shop only needs to display its QR code.": "షాప్ నమోదుకు సుమారు రెండు నిమిషాలు, దానికి తోడు Windows ప్రింట్ ఏజెంట్‌ను ఒకసారి ఇన్‌స్టాల్ చేయడం. ఆ తర్వాత షాప్ తన QR కోడ్‌ను ప్రదర్శిస్తే చాలు.",
    "Access, the Shop ID, and the print-relay agent are released to you the moment payment succeeds, and a digital licence cannot be taken back once delivered. This applies whether you change your mind, could not install the software yourself, found your printer or computer unsuitable, closed or sold the shop, received fewer print orders than you hoped, simply stopped using it, or had your account suspended for breaching our": "చెల్లింపు విజయవంతమైన ఆ క్షణమే ప్రవేశం, షాప్ ID మరియు ప్రింట్-రిలే ఏజెంట్ మీకు అందించబడతాయి; అందించిన తర్వాత డిజిటల్ లైసెన్స్‌ను వెనక్కి తీసుకోలేము. మీరు మనసు మార్చుకున్నా, సాఫ్ట్‌వేర్‌ను మీరే ఇన్‌స్టాల్ చేయలేకపోయినా, మీ ప్రింటర్/కంప్యూటర్ సరిపోలేదని తేలినా, దుకాణం మూసేసినా/అమ్మేసినా, ఆశించినంత ప్రింట్ ఆర్డర్లు రాకపోయినా, వాడటం ఆపేసినా, లేదా మా నిబంధనల ఉల్లంఘనతో ఖాతా నిలిపివేయబడినా — ఇదే వర్తిస్తుంది —",
    "Account active hone ke baad:": "ఖాతా యాక్టివ్ అయిన తర్వాత:",
    "Address": "చిరునామా",
    "Advance Feature isme nahi hai — baad me ₹199 me alag se unlock kar sakte ho": "ఇందులో అడ్వాన్స్ ఫీచర్ లేదు — తర్వాత ₹199కు విడిగా అన్‌లాక్ చేసుకోవచ్చు",
    "Advance features such as 4×6 photo sheets, A3, duplex and the resume maker may be sold as a separate unlock, at the price shown on qrseprint.in at that time.": "4×6 ఫోటో షీట్లు, A3, డూప్లెక్స్ మరియు రెజ్యూమే మేకర్ వంటి అడ్వాన్స్ ఫీచర్లు విడిగా అన్‌లాక్‌గా అమ్మబడవచ్చు — ఆ సమయంలో qrseprint.in లో చూపిన ధరకు.",
    "Agar customer se sirf counter par cash lena hai to ye section skip kar sakte ho. Online payment bhi lena hai to ye extra steps follow karo:": "కస్టమర్ నుండి కౌంటర్‌లో నగదు మాత్రమే తీసుకుంటే ఈ విభాగాన్ని దాటవేయవచ్చు. ఆన్‌లైన్ చెల్లింపు కూడా కావాలంటే ఈ అదనపు దశలు అనుసరించండి:",
    "Agar print cancel kar diya, to kya customer ko dobara upload karna padega?": "ప్రింట్ రద్దు చేస్తే, కస్టమర్ మళ్లీ అప్‌లోడ్ చేయాల్సి వస్తుందా?",
    "Agent Program": "ఏజెంట్ ప్రోగ్రామ్",
