    "Alag software, alag jhanjhat": "వేరే సాఫ్ట్‌వేర్, వేరే తలనొప్పి",
    "All Printer": "అన్ని ప్రింటర్లు",
    "Amount": "మొత్తం",
    "Any figures shown on qrseprint.in — such as prints per day, monthly earnings, or how quickly a plan pays for itself — are": "qrseprint.in లో చూపిన ఏ సంఖ్యలైనా — రోజుకు ప్రింట్లు, నెలవారీ ఆదాయం, లేదా ప్లాన్ ఎంత త్వరగా వసూలవుతుంది వంటివి —",
    "Any printer that is already installed on the shop's Windows PC — HP, Canon, Epson, Brother and others, inkjet or laser. A Wi-Fi printer is not required, because printing is done by the shop's PC, not by the phone.": "షాప్ Windows PCలో ఇప్పటికే ఇన్‌స్టాల్ అయిన ఏ ప్రింటర్ అయినా — HP, Canon, Epson, Brother మరియు ఇతరాలు, ఇంక్‌జెట్ లేదా లేజర్. Wi-Fi ప్రింటర్ అవసరం లేదు, ఎందుకంటే ప్రింటింగ్ చేసేది షాప్ PC, ఫోన్ కాదు.",
