    "Contact Us": "మమ్మల్ని సంప్రదించండి",
    "Cookies and local storage": "కుకీలు మరియు లోకల్ స్టోరేజ్",
    "Copy the design, content, or code of qrseprint.in for a competing product.": "పోటీ ఉత్పత్తి కోసం qrseprint.in డిజైన్, కంటెంట్ లేదా కోడ్‌ను కాపీ చేయడం.",
    "Counter Pe Dena Hai": "కౌంటర్‌లో చెల్లించాలి",
    "Creator's Focus": "సృష్టికర్త దృష్టి",
    "Customer Ka Bharosa": "కస్టమర్ నమ్మకం",
    "Customer Payment Kaise Lena Hai": "కస్టమర్ చెల్లింపు ఎలా తీసుకోవాలి",
    "Customer QR se 6 designs me resume banaye aur print kare — aapki extra kamai, zero mehnat.": "కస్టమర్ QR ద్వారా 6 డిజైన్లలో రెజ్యూమే తయారు చేసి ప్రింట్ చేసుకోవచ్చు — మీకు అదనపు ఆదాయం, శ్రమ సున్నా.",
    "Customer ek saath 5-10 files bheje (PDF + photo mix) — ek payment, sahi order me print.": "కస్టమర్ ఒకేసారి 5-10 ఫైళ్లు పంపవచ్చు (PDF + ఫోటో కలిపి) — ఒకే చెల్లింపు, సరైన వరుసలో ప్రింట్.",
    "Customer ka pendrive lagao = virus ka khatra. PC slow, files corrupt, kabhi-kabhi poora system hi baith jata hai.": "కస్టమర్ పెన్‌డ్రైవ్ పెడితే = వైరస్ ప్రమాదం. PC నెమ్మది, ఫైళ్లు పాడు, ఒక్కోసారి సిస్టమ్ మొత్తం ఆగిపోతుంది.",
    "Customer ke phone se": "కస్టమర్ ఫోన్ నుండి",
    "Customer khud crop, rotate, brightness theek karta hai — aapse \"thoda seedha kar do\" nahi bolega.": "కస్టమర్ తానే క్రాప్, రొటేట్, ప్రకాశం సరిచేసుకుంటాడు — \"కొంచెం సరిచేయండి\" అని మిమ్మల్ని అడగడు.",
    "Customer ko sirf QR scan karna hai, document upload karna hai, payment complete karni hai — aur print automatically start ho jata hai. Na pendrive ki zarurat, na WhatsApp par file bhejne ka jhanjhat, na manual file handling.": "కస్టమర్ చేయాల్సిందల్లా QR స్కాన్ చేయడం, పత్రాన్ని అప్‌లోడ్ చేయడం, చెల్లింపు పూర్తి చేయడం — ప్రింట్ దానంతట అదే మొదలవుతుంది. పెన్‌డ్రైవ్ అవసరం లేదు, వాట్సాప్‌లో ఫైల్ పంపే తలనొప్పి లేదు, చేతితో ఫైల్ నిర్వహణ లేదు.",
    "Customer mobile number": "కస్టమర్ మొబైల్ నంబర్",
    "Customer scan,": "కస్టమర్ స్కాన్,",
    "Customers who upload documents through a QR Se Print portal are solely responsible for what they send — its legality, its copyright, and its appropriateness. We do not open, review, moderate, or approve customer documents, and files are deleted immediately after printing as described in our": "QR Se Print పోర్టల్ ద్వారా పత్రాలు అప్‌లోడ్ చేసే కస్టమర్లే తాము పంపిన దానికి పూర్తి బాధ్యులు — దాని చట్టబద్ధత, కాపీరైట్, మరియు ఔచిత్యం. కస్టమర్ పత్రాలను మేము తెరవము, సమీక్షించము, నియంత్రించము, ఆమోదించము; మా విధానంలో చెప్పినట్టు ప్రింట్ అయిన వెంటనే ఫైళ్లు తొలగించబడతాయి —",
    "Cyber Cafes": "సైబర్ కేఫ్‌లు",
    "Cyber cafes, internet cafes, stationery and photocopy shops, DTP centres and print shops in India — any small shop that prints documents for walk-in customers.": "భారతదేశంలోని సైబర్ కేఫ్‌లు, ఇంటర్నెట్ కేఫ్‌లు, స్టేషనరీ మరియు ఫోటోకాపీ షాపులు, DTP కేంద్రాలు మరియు ప్రింట్ షాపులు — వచ్చే కస్టమర్లకు పత్రాలు ప్రింట్ చేసే ఏ చిన్న దుకాణమైనా.",
    "Daily use kiya, improve kiya, aur asli feedback ke basis par features add kiye. Jo kaam nahi aaya, hata diya.": "రోజూ వాడాను, మెరుగుపరిచాను, నిజమైన అభిప్రాయాల ఆధారంగా ఫీచర్లు జోడించాను. పనికిరానివి తీసేశాను.",
