    "Email se bhejo": "ఇమెయిల్‌లో పంపండి",
    "Every prospective shop gets a free demo on qrseprint.in with no payment and no card details. The demo runs the real software so you can test it with your own printer before deciding. Demo shops may be limited in duration and may be reset or removed at any time.": "ఆసక్తి ఉన్న ప్రతి షాప్‌కూ qrseprint.in లో ఉచిత డెమో లభిస్తుంది — చెల్లింపు లేదు, కార్డు వివరాలు లేవు. డెమోలో నిజమైన సాఫ్ట్‌వేరే నడుస్తుంది, కాబట్టి నిర్ణయించుకునే ముందు మీ సొంత ప్రింటర్‌తో పరీక్షించవచ్చు. డెమో షాపుల కాలపరిమితి పరిమితం కావచ్చు, ఎప్పుడైనా రీసెట్ లేదా తొలగింపు జరగవచ్చు.",
    "Every shop has its own admin panel on qrseprint.in with a print log. That log records": "ప్రతి షాప్‌కు qrseprint.in లో ప్రింట్ లాగ్‌తో కూడిన సొంత అడ్మిన్ ప్యానెల్ ఉంటుంది. ఆ లాగ్ నమోదు చేసేది",
    "Every shop running QR Se Print remains fully responsible for:": "QR Se Print నడుపుతున్న ప్రతి షాప్ వీటికి పూర్తి బాధ్యత వహిస్తుంది:",
