    "File jaisi hai waisi hi print hogi — sabse saaf aur sabse tez": "ఫైల్ ఉన్నది ఉన్నట్టే ప్రింట్ అవుతుంది — అత్యంత స్పష్టం, అత్యంత వేగం",
    "File lena": "ఫైల్ తీసుకోవడం",
    "File padhi nahi ja saki": "ఫైల్ చదవలేకపోయాము",
    "File print ke 90 minute baad KHUD delete. Na aapke paas rahegi, na kisi aur ke — privacy pakki.": "ఫైల్ ప్రింట్ అయిన 90 నిమిషాల తర్వాత దానంతట అదే తొలగిపోతుంది. మీ దగ్గరా ఉండదు, ఇంకెవరి దగ్గరా ఉండదు — గోప్యత పక్కా.",
    "File receive karo, download karo, payment lo, phir manually print do. Peak hours me line lag jaati thi.": "ఫైల్ స్వీకరించండి, డౌన్‌లోడ్ చేయండి, చెల్లింపు తీసుకోండి, తర్వాత చేతితో ప్రింట్ ఇవ్వండి. రద్దీ వేళల్లో లైన్ పెరిగిపోయేది.",
    "File upload ke baad, file kahaan store hoti hai?": "ఫైల్ అప్‌లోడ్ తర్వాత, ఫైల్ ఎక్కడ నిల్వ అవుతుంది?",
    "Files 100% safe hain": "ఫైళ్లు 100% సురక్షితం",
    "Files are stored temporarily only to complete the print job and are removed afterwards. Each shop sees only its own jobs. The full retention details are on the Privacy Policy page.": "ప్రింట్ జాబ్ పూర్తి చేయడానికి మాత్రమే ఫైళ్లు తాత్కాలికంగా ఉంచబడతాయి, తర్వాత తొలగించబడతాయి. ప్రతి షాప్ తన సొంత జాబ్‌లను మాత్రమే చూస్తుంది. పూర్తి వివరాలు గోప్యతా విధాన పేజీలో ఉన్నాయి.",
    "Files uploaded by customers": "కస్టమర్లు అప్‌లోడ్ చేసిన ఫైళ్లు",
    "Form bharo — message seedha humare WhatsApp ya Email par pahunchega": "ఫారం నింపండి — సందేశం నేరుగా మా వాట్సాప్ లేదా ఇమెయిల్‌కు చేరుతుంది",
    "Free demo": "ఉచిత డెమో",
    "GST ya current account nahi hai? Koi baat nahi —": "GST లేదా కరెంట్ ఖాతా లేదా? పర్వాలేదు —",
    "Ghumana, kaatna, ujaala-gehra, ya aur document jodna ho to": "తిప్పడం, కత్తిరించడం, వెలుగు-చీకటి సర్దుబాటు, లేదా మరో పత్రం జోడించాలంటే",
    "Governing law": "వర్తించే చట్టం",
    "Haan, dobara upload karna padega. Hamari policy hai ki koi file store nahi ki jaati — chahe print ho ya cancel. Ye aap khud verify kar sakte ho: System Tray me QR Se Print icon par right-click karke": "అవును, మళ్లీ అప్‌లోడ్ చేయాల్సి వస్తుంది. ఏ ఫైల్‌నూ నిల్వ చేయకూడదన్నదే మా విధానం — ప్రింట్ అయినా, రద్దు అయినా. దీన్ని మీరే ధృవీకరించుకోవచ్చు: సిస్టమ్ ట్రేలో QR Se Print ఐకాన్‌పై రైట్-క్లిక్ చేసి",
    "Hamara Mission": "మా లక్ష్యం",
    "Hamara Vision": "మా దృష్టి",
    "Hamara goal sirf software dena nahi, balki har shop owner ko apna business aur professional, fast aur efficient banane me help karna hai.": "మా లక్ష్యం కేవలం సాఫ్ట్‌వేర్ ఇవ్వడం కాదు — ప్రతి షాప్ యజమాని తన వ్యాపారాన్ని మరింత వృత్తిపరంగా, వేగంగా, సమర్థంగా చేసుకోవడంలో సహాయపడటం.",
    "Hamara vision hai ki QR Se Print India ka sabse trusted Smart Printing Platform bane — jahan har print shop bina expensive infrastructure ke smart aur automated printing service de sake.": "QR Se Print భారతదేశంలో అత్యంత నమ్మదగిన స్మార్ట్ ప్రింటింగ్ ప్లాట్‌ఫారమ్ కావాలన్నదే మా దృష్టి — ఖరీదైన మౌలిక సదుపాయాలు లేకుండానే ప్రతి ప్రింట్ షాప్ స్మార్ట్, ఆటోమేటెడ్ ప్రింటింగ్ సేవ ఇవ్వగలగాలి.",
    "Happy Customers": "సంతోషకరమైన కస్టమర్లు",
    "Har chhote page ke chaaro taraf patli line": "ప్రతి చిన్న పేజీ చుట్టూ సన్నని గీత",
    "Har cyber cafe / print shop wale ka roz ka dard": "ప్రతి సైబర్ కేఫ్ / ప్రింట్ షాప్ యజమాని రోజువారీ బాధ",
    "Har print me haath lagao": "ప్రతి ప్రింట్‌కు చేతితో పని",
    "Har shop onboard karne par flat ₹100 commission": "ప్రతి షాప్‌ను చేర్చినందుకు ఫ్లాట్ ₹100 కమీషన్",
    "Har tarah ke printer ka support — WiFi printer ki zarurat nahi": "అన్ని రకాల ప్రింటర్లకు మద్దతు — WiFi ప్రింటర్ అవసరం లేదు",
    "He has professional experience as a 2D Animator & Video Editor, Animation Faculty, and Team Leader in the animation industry, followed by entrepreneurship and technology-focused business operations.": "యానిమేషన్ రంగంలో 2D యానిమేటర్ & వీడియో ఎడిటర్, యానిమేషన్ ఫ్యాకల్టీ మరియు టీమ్ లీడర్‌గా వృత్తిపరమైన అనుభవం ఆయనకు ఉంది; ఆ తర్వాత వ్యవస్థాపకత మరియు సాంకేతికత ఆధారిత వ్యాపార నిర్వహణ.",
    "His technical and professional certifications include Google Digital Marketing, IIBF Banking & Finance, Insurance Business, and UIDAI Aadhaar Operator/Supervisor. In 2026, he also completed an AI certification from Google, strengthening his knowledge of modern Artificial Intelligence technologies and their practical applications.": "ఆయన సాంకేతిక మరియు వృత్తిపరమైన ధృవపత్రాలలో Google Digital Marketing, IIBF Banking & Finance, Insurance Business, మరియు UIDAI ఆధార్ ఆపరేటర్/సూపర్‌వైజర్ ఉన్నాయి. 2026లో Google నుండి AI ధృవపత్రం కూడా పూర్తి చేసి, ఆధునిక కృత్రిమ మేధ సాంకేతికతలు మరియు వాటి ఆచరణాత్మక వినియోగంపై తన పరిజ్ఞానాన్ని బలోపేతం చేసుకున్నారు.",
