    "How much does QR Se Print cost?": "QR Se Print ఖర్చు ఎంత?",
    "How to Setup": "సెటప్ ఎలా చేయాలి",
    "Hum believe karte hain ki technology ka asli purpose logon ka kaam easy banana hai. Isi soch ke saath QR Se Print develop kiya gaya hai, taaki har print shop bina expensive hardware ya complicated setup ke ek modern self-service printing experience de sake.": "సాంకేతికత అసలు ఉద్దేశం మనుషుల పనిని సులభం చేయడమేనని మేము నమ్ముతాము. అదే ఆలోచనతో QR Se Print రూపొందించబడింది — ఖరీదైన హార్డ్‌వేర్ లేదా క్లిష్టమైన సెటప్ లేకుండానే ప్రతి ప్రింట్ షాప్ ఆధునిక సెల్ఫ్-సర్వీస్ ప్రింటింగ్ అనుభవాన్ని ఇవ్వగలగాలి.",
    "Hum lagatar naye features, better security, faster performance aur reliable technology par kaam kar rahe hain, taaki har business confidently digital printing ka future apna sake.": "కొత్త ఫీచర్లు, మెరుగైన భద్రత, వేగవంతమైన పనితీరు మరియు నమ్మదగిన సాంకేతికతపై మేము నిరంతరం పని చేస్తున్నాము, తద్వారా ప్రతి వ్యాపారం డిజిటల్ ప్రింటింగ్ భవిష్యత్తును ధైర్యంగా స్వీకరించగలదు.",
    "If the way qrseprint.in handles data changes, this page is updated and the date at the top changes with it. Anything that materially affects shops will also be shown in the admin panel.": "qrseprint.in డేటాను నిర్వహించే విధానం మారితే, ఈ పేజీ నవీకరించబడుతుంది మరియు పైన ఉన్న తేదీ కూడా మారుతుంది. షాపులపై గణనీయమైన ప్రభావం చూపే విషయాలు అడ్మిన్ ప్యానెల్‌లోనూ చూపబడతాయి.",
    "If you do not agree with any part of this Disclaimer, please stop using qrseprint.in and the QR Se Print software.": "ఈ నిరాకరణలోని ఏ భాగంతోనైనా మీరు ఏకీభవించకపోతే, qrseprint.in మరియు QR Se Print సాఫ్ట్‌వేర్ వాడటం ఆపండి.",
    "In five steps: (1) the shop displays its QR code, (2) the customer scans it and opens the link in any phone browser, (3) the customer uploads a PDF or photo and picks black & white or colour, pages and copies, (4) the customer pays online or chooses pay-at-counter, (5) the shop's printer prints the job automatically.": "ఐదు దశల్లో: (1) షాప్ తన QR కోడ్‌ను ప్రదర్శిస్తుంది, (2) కస్టమర్ దాన్ని స్కాన్ చేసి ఏ ఫోన్ బ్రౌజర్‌లోనైనా లింక్ తెరుస్తాడు, (3) కస్టమర్ PDF లేదా ఫోటో అప్‌లోడ్ చేసి బ్లాక్-వైట్ లేదా రంగు, పేజీలు, కాపీలు ఎంచుకుంటాడు, (4) కస్టమర్ ఆన్‌లైన్‌లో చెల్లిస్తాడు లేదా కౌంటర్ చెల్లింపు ఎంచుకుంటాడు, (5) షాప్ ప్రింటర్ జాబ్‌ను ఆటోమేటిక్‌గా ప్రింట్ చేస్తుంది.",
    "Information we collect": "మేము సేకరించే సమాచారం",
    "Inside the software": "సాఫ్ట్‌వేర్ లోపల",
    "Install hote hi software apne aap minimize hoke": "ఇన్‌స్టాల్ కాగానే సాఫ్ట్‌వేర్ దానంతట అదే చిన్నదై",
    "Instantly": "వెంటనే",
    "Instead of a refund you get the service delivered:": "వాపసుకు బదులు మీకు సేవ పూర్తిగా అందించబడుతుంది:",
    "Intellectual property": "మేధో సంపత్తి",
    "Internet band? Jobs queue me. Wapas aate hi sab print. Auto-update bhi khud hota hai.": "ఇంటర్నెట్ పోయిందా? జాబ్‌లు క్యూలో ఉంటాయి. తిరిగి రాగానే అన్నీ ప్రింట్. ఆటో-అప్‌డేట్ కూడా దానంతట అదే.",
    "Internet, uptime and updates": "ఇంటర్నెట్, అప్‌టైమ్ మరియు అప్‌డేట్‌లు",
    "Is QR Se Print available across India?": "QR Se Print భారతదేశమంతటా అందుబాటులో ఉందా?",
    "Is it safe? What happens to the customer's file?": "ఇది సురక్షితమా? కస్టమర్ ఫైల్ ఏమవుతుంది?",
    "Isi problem ko theek karne ke liye QR Se Print banaya — bechne ke liye nahi, apna kaam aasan karne ke liye.": "ఈ సమస్యను పరిష్కరించడానికే QR Se Print తయారు చేశాను — అమ్మడానికి కాదు, నా పని సులభం చేసుకోవడానికి.",
    "Isliye isme wahi features milte hain jo ek asli print shop ki roz ki zarurat dekh kar bane hain — sirf dikhane ke liye nahi.": "అందుకే ఇందులో నిజమైన ప్రింట్ షాప్ రోజువారీ అవసరాలను చూసి తయారైన ఫీచర్లే ఉన్నాయి — కేవలం చూపించడానికి కాదు.",
    "Jab apni shop me system bharose ka ho gaya, tab laga ki ye doosre Cyber Cafes aur Print Shops ke bhi kaam aayega.": "నా షాప్‌లో వ్యవస్థ నమ్మదగినదిగా మారాక, ఇది ఇతర సైబర్ కేఫ్‌లు, ప్రింట్ షాపులకూ ఉపయోగపడుతుందని అనిపించింది.",
    "Jab meri dukaan pe chal gaya, tab doosre shop walon ke liye khola. Isliye isme wahi cheezein hain jo": "నా దుకాణంలో పనిచేసిన తర్వాతే ఇతర షాప్ వారికి తెరిచాను. అందుకే ఇందులో అవే ఉన్నాయి —",
    "Jharkhand me bana": "జార్ఖండ్‌లో తయారైంది",
    "Jharkhand, India": "జార్ఖండ్, భారతదేశం",
    "Jo bhi naya advance feature banega, apne aap mil jayega — dobara paisa nahi": "కొత్తగా ఏ అడ్వాన్స్ ఫీచర్ వచ్చినా దానంతట అదే లభిస్తుంది — మళ్లీ డబ్బు లేదు",
    "Jo software download kiya, use apne dukaan ke computer me install karo. Install hote waqt": "డౌన్‌లోడ్ చేసిన సాఫ్ట్‌వేర్‌ను మీ దుకాణం కంప్యూటర్‌లో ఇన్‌స్టాల్ చేయండి. ఇన్‌స్టాల్ సమయంలో",
    "Jo-jo milta hai, sab ek jagah": "లభించేవన్నీ ఒకే చోట",
