    "Lifetime — aaj ka bhi, aane wala bhi": "జీవితకాలం — ఈనాటిదీ, రాబోయేదీ",
    "Lifetime — ek baar pay, koi renewal nahi": "జీవితకాలం — ఒకేసారి చెల్లింపు, పునరుద్ధరణ లేదు",
