    "Login karo → Download tab se QR + Software lo → PC me install karo → Settings me printer select karo → QR scan karke test print nikalo. Bas itna hi hai.": "లాగిన్ చేయండి → Download ట్యాబ్ నుండి QR + సాఫ్ట్‌వేర్ తీసుకోండి → PCలో ఇన్‌స్టాల్ చేయండి → Settingsలో ప్రింటర్ ఎంచుకోండి → QR స్కాన్ చేసి టెస్ట్ ప్రింట్ తీయండి. అంతే.",
    "Logout karke dobara Login": "లాగ్ అవుట్ చేసి మళ్లీ లాగిన్",
    "Made in": "తయారీ",
    "Mahine ki print kamai": "నెలవారీ ప్రింట్ ఆదాయం",
