    "Main": "ప్రధాన",
    "Making printing smarter, faster & simpler.": "ప్రింటింగ్‌ను తెలివిగా, వేగంగా & సులభంగా చేస్తున్నాము.",
    "Matlab license lene ke baad har shop ka poora paisa aapka — hum usme se ek rupaya nahi lete.": "అంటే లైసెన్స్ తీసుకున్న తర్వాత ప్రతి షాప్ మొత్తం డబ్బు మీదే — అందులో మేము ఒక్క రూపాయి తీసుకోము.",
