    "Money: your customers pay you directly": "డబ్బు: మీ కస్టమర్లు నేరుగా మీకే చెల్లిస్తారు",
    "Multi-file Print": "బహుళ-ఫైల్ ప్రింట్",
    "NO FILE STORED": "ఏ ఫైల్‌నూ నిల్వ చేయము",
    "Na alag photo tool, na alag resume software, na alag hisaab ki copy. Ek QR — aur dukaan ka poora kaam.": "వేరే ఫోటో టూల్ లేదు, వేరే రెజ్యూమే సాఫ్ట్‌వేర్ లేదు, వేరే లెక్కల పుస్తకం లేదు. ఒక QR — దుకాణం పని మొత్తం.",
    "Naya Print Karo": "కొత్త ప్రింట్ చేయండి",
    "Net Jaye To Bhi Safe": "ఇంటర్నెట్ పోయినా సురక్షితం",
    "No File Transfer": "ఫైల్ ట్రాన్స్‌ఫర్ అవసరం లేదు",
    "No Pendrive": "పెన్‌డ్రైవ్ అవసరం లేదు",
    "No WhatsApp": "వాట్సాప్ అవసరం లేదు",
    "No Wi-Fi Printer": "Wi-Fi ప్రింటర్ అవసరం లేదు",
    "No copies. No backups. Nothing kept after the print.": "నకళ్లు లేవు. బ్యాకప్‌లు లేవు. ప్రింట్ తర్వాత ఏదీ ఉంచబడదు.",
    "No system is perfectly secure, and we cannot promise absolute safety. Shop owners must protect their own Shop ID, password, and the computer running the print-relay agent.": "ఏ వ్యవస్థా పూర్తిగా సురక్షితం కాదు, సంపూర్ణ భద్రతకు మేము హామీ ఇవ్వలేము. షాప్ యజమానులు తమ షాప్ ID, పాస్‌వర్డ్ మరియు ప్రింట్-రిలే ఏజెంట్ నడిచే కంప్యూటర్‌ను రక్షించుకోవాలి.",
    "No. If your existing printer prints from your Windows PC today, it will work with QR Se Print. You only install a small print agent on that PC.": "అవసరం లేదు. మీ ప్రస్తుత ప్రింటర్ ఈరోజు మీ Windows PC నుండి ప్రింట్ చేస్తుంటే, అది QR Se Printతో పనిచేస్తుంది. ఆ PCలో ఒక చిన్న ప్రింట్ ఏజెంట్ ఇన్‌స్టాల్ చేస్తే చాలు.",
    "No. The customer needs only a phone camera and a browser. There is nothing to download, no sign-up and no account.": "లేదు. కస్టమర్‌కు ఫోన్ కెమెరా మరియు బ్రౌజర్ మాత్రమే కావాలి. డౌన్‌లోడ్ చేయాల్సినది ఏదీ లేదు, సైన్-అప్ లేదు, ఖాతా లేదు.",
    "Nothing in QR Se Print creates a partnership, franchise, agency, or employment relationship with any shop.": "QR Se Printలో ఏదీ ఏ షాప్‌తోనూ భాగస్వామ్యం, ఫ్రాంచైజీ, ఏజెన్సీ లేదా ఉద్యోగ సంబంధాన్ని ఏర్పరచదు.",
    "Nothing is lost. Jobs stay safely in the queue, and when the connection returns the print agent picks them up and prints them automatically.": "ఏదీ పోదు. జాబ్‌లు క్యూలో సురక్షితంగా ఉంటాయి, కనెక్షన్ తిరిగి రాగానే ప్రింట్ ఏజెంట్ వాటిని తీసుకుని ఆటోమేటిక్‌గా ప్రింట్ చేస్తుంది.",
    "ORDER #...": "ఆర్డర్ #...",
    "Online": "ఆన్‌లైన్",
    "Online payment (Razorpay/Cashfree) SEEDHA aapko. Hum beech me nahi —": "ఆన్‌లైన్ చెల్లింపు (Razorpay/Cashfree) నేరుగా మీకే. మేము మధ్యలో లేము —",
    "Online payments are handled by Razorpay or the shop’s own UPI, and settle": "ఆన్‌లైన్ చెల్లింపులను Razorpay లేదా షాప్ సొంత UPI నిర్వహిస్తుంది, మరియు చేరుతాయి",
    "Online payments on qrseprint.in are handled by": "qrseprint.in లోని ఆన్‌లైన్ చెల్లింపులను నిర్వహించేది",
    "Opens on every print and shows each step, including the file being deleted from the PC and from the server.": "ప్రతి ప్రింట్‌కూ తెరుచుకుని ప్రతి దశనూ చూపుతుంది — ఫైల్ PC నుండి, సర్వర్ నుండి తొలగించబడటంతో సహా.",
