    "Paid plans published on qrseprint.in include a monthly plan and a one-time lifetime plan. On purchase you get a limited, non-transferable licence to install and run the QR Se Print agent at your own shop. You may not:": "qrseprint.in లో ప్రచురించిన చెల్లింపు ప్లాన్లలో నెలవారీ ప్లాన్ మరియు ఒకేసారి చెల్లించే జీవితకాల ప్లాన్ ఉన్నాయి. కొనుగోలుతో మీ సొంత షాప్‌లో QR Se Print ఏజెంట్‌ను ఇన్‌స్టాల్ చేసి నడపడానికి పరిమిత, బదిలీ చేయలేని లైసెన్స్ లభిస్తుంది. మీరు వీటిని చేయకూడదు:",
    "Paisa Seedha Aapke Account": "డబ్బు నేరుగా మీ ఖాతాలోకి",
    "Paise dene se pehle free demo se poora software try karo. Payment ke baad refund nahi milta. Par install nahi kar pa rahe to tension mat lo — WhatsApp ya AnyDesk se hum khud setup karke denge, jab tak chalu na ho jaye.": "డబ్బు చెల్లించే ముందు ఉచిత డెమోతో సాఫ్ట్‌వేర్ మొత్తాన్ని ప్రయత్నించి చూడండి. చెల్లింపు తర్వాత వాపసు ఉండదు. కానీ ఇన్‌స్టాల్ చేయలేకపోతే ఆందోళన వద్దు — వాట్సాప్ లేదా AnyDesk ద్వారా మేమే సెటప్ చేసి ఇస్తాము, పని మొదలయ్యే వరకు.",
    "Panel me apni Razorpay key daalo — shops ka poora paisa seedha aapke bank me aayega.": "ప్యానెల్‌లో మీ Razorpay కీ పెట్టండి — షాపుల మొత్తం డబ్బు నేరుగా మీ బ్యాంకుకు వస్తుంది.",
