    "Register Karo — Agla Step: Setup Fee ›": "నమోదు చేయండి — తదుపరి దశ: సెటప్ ఫీజు ›",
    "Register Karo — Agla Step: ₹899 ›": "నమోదు చేయండి — తదుపరి దశ: ₹899 ›",
    "Register hone ke baad QR Code + Print Agent turant milega.": "నమోదు తర్వాత QR కోడ్ + ప్రింట్ ఏజెంట్ వెంటనే లభిస్తాయి.",
    "Register karne ke baad:": "నమోదు చేసిన తర్వాత:",
    "Registration ke baad payment poora hote hi aapko turant ek": "నమోదు తర్వాత చెల్లింపు పూర్తి కాగానే మీకు వెంటనే ఒక",
    "Registration ke time jahan business website maangi jaaye, wahaan": "నమోదు సమయంలో వ్యాపార వెబ్‌సైట్ అడిగిన చోట",
    "Regular updates aur improvements": "క్రమం తప్పకుండా అప్‌డేట్‌లు మరియు మెరుగుదలలు",
    "Required": "అవసరం",
    "Resell, rent, sub-licence, or redistribute the software or your Shop ID;": "సాఫ్ట్‌వేర్ లేదా మీ షాప్ IDని పునఃవిక్రయం, అద్దె, ఉప-లైసెన్స్, లేదా పంపిణీ చేయడం;",
    "Resume Maker": "రెజ్యూమే మేకర్",
    "Reverse-engineer, decompile, patch, or tamper with the agent or its auto-update mechanism;": "ఏజెంట్ లేదా దాని ఆటో-అప్‌డేట్ వ్యవస్థను రివర్స్-ఇంజనీర్, డీకంపైల్, ప్యాచ్ లేదా మార్పు చేయడం;",
    "Right-click the tray icon for status, printer, approval mode, logs and updates.": "స్థితి, ప్రింటర్, ఆమోద మోడ్, లాగ్‌లు మరియు అప్‌డేట్‌ల కోసం ట్రే ఐకాన్‌పై రైట్-క్లిక్ చేయండి.",
    "Roz ka wahi jhanjhat": "రోజూ అదే తలనొప్పి",
    "Ruko, band mat karo": "ఆగండి, మూసివేయకండి",
    "Ruko…": "ఆగండి…",
    "Run a modified build, or block updates that we publish for security or compatibility.": "మార్పు చేసిన బిల్డ్‌ను నడపడం, లేదా భద్రత/అనుకూలత కోసం మేము విడుదల చేసే అప్‌డేట్‌లను అడ్డుకోవడం.",
    "Running the shop is entirely yours. You are responsible for:": "దుకాణం నడపడం పూర్తిగా మీదే. వీటికి మీరే బాధ్యులు:",
    "Rupesh Kumar Mahato apna Cyber Cafe chalate hain. Roz customers WhatsApp se file bhejte, ya pendrive lekar aate.": "Rupesh Kumar Mahato తన సొంత సైబర్ కేఫ్ నడుపుతారు. రోజూ కస్టమర్లు వాట్సాప్‌లో ఫైల్ పంపేవారు, లేదా పెన్‌డ్రైవ్ తీసుకొచ్చేవారు.",
    "Rupesh Kumar Mahato is a technology-focused entrepreneur, creative professional, and the creator of": "Rupesh Kumar Mahato సాంకేతికతపై దృష్టి పెట్టిన వ్యాపారవేత్త, సృజనాత్మక నిపుణుడు, మరియు దీని సృష్టికర్త —",
    "Rupesh focuses on combining technology, automation, AI, and creative problem-solving to build practical solutions for everyday business needs. QR Se Print is an example of this approach — turning a simple QR-based workflow into an automated printing solution that can be used by businesses without requiring complex technical infrastructure.": "రోజువారీ వ్యాపార అవసరాలకు ఆచరణాత్మక పరిష్కారాలు రూపొందించడానికి సాంకేతికత, ఆటోమేషన్, AI మరియు సృజనాత్మక సమస్య-పరిష్కారాన్ని కలపడంపై Rupesh దృష్టి పెడతారు. QR Se Print ఈ విధానానికి ఒక ఉదాహరణ — సరళమైన QR ఆధారిత పద్ధతిని, క్లిష్టమైన సాంకేతిక మౌలిక సదుపాయాలు అవసరం లేకుండా వ్యాపారాలు వాడగలిగే ఆటోమేటెడ్ ప్రింటింగ్ పరిష్కారంగా మార్చడం.",
    "SCAN": "స్కాన్",
    "Saaf aur sharp print": "శుభ్రమైన, స్పష్టమైన ప్రింట్",
