    "What happens to prints if the internet goes down?": "ఇంటర్నెట్ పోతే ప్రింట్లు ఏమవుతాయి?",
    "Customer jobs stay safe in the queue. As soon as the internet is back, the software picks up the jobs and prints them — nothing is lost.": "జాబ్‌లు క్యూలో సురక్షితంగా ఉంటాయి. ఇంటర్నెట్ తిరిగి రాగానే సాఫ్ట్‌వేర్ వాటిని తీసుకుని ప్రింట్ చేస్తుంది — ఏదీ పోదు.",
    "Do tarike: counter par cash, ya online payment (Razorpay/PhonePe) jo seedha aapke account me jata hai. Hum beech me nahi aate — koi commission nahi, unlimited prints.": "రెండు మార్గాలు: కౌంటర్‌లో నగదు, లేదా ఆన్‌లైన్ చెల్లింపు (Razorpay/PhonePe) — అది నేరుగా మీ ఖాతాలోకే వెళుతుంది. మేము మధ్యలో ఉండము — కమిషన్ లేదు, అపరిమిత ప్రింట్లు.",
    "Free demo se shuru karo. Phir Rs 399/month ka monthly plan ya Rs 999 one-time lifetime plan — ek baar do, hamesha chalao. Koi hidden charge nahi, koi per-print commission nahi.": "ఉచిత డెమోతో మొదలుపెట్టండి. ఆ తర్వాత నెలకు ₹399 ప్లాన్ లేదా ఒకేసారి ₹999 లైఫ్‌టైమ్ ప్లాన్ — ఒకసారి కట్టి, ఎప్పటికీ వాడండి. దాచిన ఛార్జీలు లేవు, ప్రతి ప్రింట్‌కు కమిషన్ లేదు.",
    "Har Windows printer ke saath — HP, Canon, Epson, Brother, sab. B&W aur Color ke liye alag printer set kar sakte ho. Advance me 4x6 photo printer, A3 bada printer aur duplex (dono side) printing bhi support hai.": "ప్రతి Windows ప్రింటర్‌తో — HP, Canon, Epson, Brother, అన్నీ. బ్లాక్-వైట్‌కి, రంగుకి వేర్వేరు ప్రింటర్లు పెట్టుకోవచ్చు. అడ్వాన్స్‌లో 4x6 ఫోటో ప్రింటర్, పెద్ద A3 ప్రింటర్ మరియు డుప్లెక్స్ (రెండు వైపులా) ప్రింటింగ్ కూడా ఉంది.",
    "Shop par laga QR code scan karo, file select karo (PDF, photo — ek saath kai files), edit karo (crop, rotate, brightness), payment karo (online ya counter cash) — print automatic nikal jata hai. Poora kaam customer ke phone se, 1 minute me.": "షాపులో ఉన్న QR కోడ్ స్కాన్ చేసి, ఫైళ్లు ఎంచుకుని (PDF, ఫోటో — ఒకేసారి చాలా), ఎడిట్ చేసి (క్రాప్, తిప్పడం, ప్రకాశం), డబ్బు చెల్లిస్తే (ఆన్‌లైన్ లేదా కౌంటర్‌లో నగదు) — ప్రింట్ దానంతట అదే వస్తుంది. అంతా కస్టమర్ ఫోన్ నుండే, ఒక నిమిషంలో.",
    "WhatsApp me aapka personal number public ho jata hai, chat me files kho jaati hain, aur hisaab manually rakhna padta hai. QR Se Print me number private rehta hai, har print ka payment record automatic banta hai, aur customer ki file print ke 90 minute baad khud delete ho jaati hai.": "WhatsApp‌లో మీ వ్యక్తిగత నంబర్ అందరికీ తెలిసిపోతుంది, చాట్‌లో ఫైళ్లు పోతాయి, లెక్క కూడా చేతితో రాయాలి. QR Se Print‌లో మీ నంబర్ గోప్యంగానే ఉంటుంది, ప్రతి ప్రింట్‌కు చెల్లింపు రికార్డు దానంతట అదే అవుతుంది, కస్టమర్ ఫైల్ ప్రింట్ అయిన 90 నిమిషాల తర్వాత తనంతట తానే తొలగిపోతుంది.",
    "QR Se Print cyber cafe aur print shop ke liye ek automatic print software hai. Aap apni shop ka QR code lagate ho — customer apne phone se scan karke file upload karta hai, payment karta hai, aur print aapke printer se automatic nikal jata hai. Na WhatsApp pe file mangni padti hai, na pendrive, na email.": "QR Se Print అనేది సైబర్ కేఫ్‌లు మరియు ప్రింట్ షాపుల కోసం ఆటోమేటిక్ ప్రింట్ సాఫ్ట్‌వేర్. మీ షాపు QR కోడ్ పెడితే చాలు — కస్టమర్ తన ఫోన్‌తో స్కాన్ చేసి ఫైల్ అప్‌లోడ్ చేసి, డబ్బు చెల్లిస్తారు, ప్రింట్ మీ ప్రింటర్ నుండి దానంతట అదే వస్తుంది. WhatsApp‌లో ఫైల్ అడగనవసరం లేదు, పెన్‌డ్రైవ్ అవసరం లేదు, ఇమెయిల్ అవసరం లేదు."
