    "They reply with the number for colour and copies": "రంగు మరియు కాపీల కోసం నంబర్‌తో బదులిస్తారు",
    "What WhatsApp's own API would cost you every month": "WhatsApp సొంత API మీకు ప్రతి నెలా ఎంత ఖర్చు అవుతుంది",
    "Sending to the printer…\nresume.pdf\n1 copy · B&W\nTotal ₹5": "ప్రింటర్‌కు పంపుతోంది…\nresume.pdf\n1 కాపీ · బ్లాక్ & వైట్\nమొత్తం ₹5",
    "The print comes out on your printer, the file is deleted": "మీ ప్రింటర్‌లో ప్రింట్ బయటకు వస్తుంది, ఫైల్ తొలగిపోతుంది",
    "Thank you! We will message you on WhatsApp as soon as this is ready.": "ధన్యవాదాలు! ఇది సిద్ధం కాగానే WhatsApp లో మీకు సందేశం పంపుతాం.",
    "Black & White selected — 1 page\n\nHow many copies?\n1 = 1 copy ₹5\n2 = 2 copies ₹10\n3 = 3 copies ₹15": "బ్లాక్ & వైట్ ఎంపిక అయింది — 1 పేజీ\n\nఎన్ని కాపీలు?\n1 = 1 కాపీ ₹5\n2 = 2 కాపీలు ₹10\n3 = 3 కాపీలు ₹15",
    "Files automatically deleted from the server and the shop owner's computer immediately after print": "ప్రింట్ అయిన వెంటనే సర్వర్ నుండి మరియు షాపు యజమాని కంప్యూటర్ నుండి ఫైళ్లు వాటంతట అవే తొలగిపోతాయి",
    "Every reply the bot sends is a paid conversation on Meta's API. This is roughly what a shop would pay:": "బాట్ పంపే ప్రతి బదులు Meta API పై చెల్లింపు సంభాషణ. ఒక షాపు సుమారుగా ఇంత చెల్లించాల్సి ఉంటుంది:",
    "Print Settings — 1 page\n\nHow do you want it?\n1 = B&W ₹5/page (₹5)\n2 = Color ₹10/page (₹10)\n\nReply 1 or 2": "ప్రింట్ సెట్టింగ్‌లు — 1 పేజీ\n\nఎలా కావాలి?\n1 = బ్లాక్ & వైట్ ₹5/పేజీ (₹5)\n2 = కలర్ ₹10/పేజీ (₹10)\n\n1 లేదా 2 అని బదులివ్వండి",
    "Printed!\n\nPay ₹5 cash at the counter and collect your print.\nYour file has been deleted.\n\nNext time just send: Hello Print": "ప్రింట్ అయింది!\n\nకౌంటర్‌లో ₹5 నగదు చెల్లించి మీ ప్రింట్ తీసుకోండి.\nమీ ఫైల్ తొలగించబడింది.\n\nవచ్చేసారి ఇది మాత్రం పంపండి: Hello Print",
    "Approximate Meta conversation charges. Your real bill depends on how many customers message you and what type of message it is.": "ఇవి సుమారు Meta సంభాషణ ఛార్జీలు. మీకు ఎంతమంది కస్టమర్లు సందేశం పంపుతారు, ఏ రకమైన సందేశం అనేదాని బట్టి మీ నిజమైన బిల్లు ఉంటుంది.",
    "Sharma Cyber Cafe — QR Se Print\n\nSend your file right here on WhatsApp.\nPDF · JPG · PNG\n\nAttachment → Document → file → Send\n\nB&W ₹5/page · Color ₹10/page": "శర్మా సైబర్ కేఫ్ — QR Se Print\n\nమీ ఫైల్‌ను ఇక్కడే WhatsApp లో పంపండి.\nPDF · JPG · PNG\n\nఅటాచ్‌మెంట్ → డాక్యుమెంట్ → ఫైల్ → పంపండి\n\nబ్లాక్ & వైట్ ₹5/పేజీ · కలర్ ₹10/పేజీ",
    "No app and no website for your customer. They scan your QR, WhatsApp opens with the message already typed, they send the file — and the print comes out at your counter.": "మీ కస్టమర్‌కు యాప్ అక్కర్లేదు, వెబ్‌సైట్ అక్కర్లేదు. వారు మీ QR స్కాన్ చేస్తారు, సందేశం ముందే టైప్ అయి WhatsApp తెరుచుకుంటుంది, వారు ఫైల్ పంపుతారు — ప్రింట్ మీ కౌంటర్‌లో బయటకు వస్తుంది."
