    "Email daalo — payment ki receipt isi par aayegi": "ఇమెయిల్ పెట్టండి — చెల్లింపు రసీదు దీనికే వస్తుంది",
    "Is photo ka format browser support nahi karta (": "ఈ ఫోటో ఫార్మాట్‌ను బ్రౌజర్ సపోర్ట్ చేయదు (",
    "Phone ya computer me pehle se rakhi photo chuno": "ఫోన్ లేదా కంప్యూటర్‌లో ఇప్పటికే ఉన్న ఫోటోను ఎంచుకోండి",
    "Registered mobile number (verification ke liye)": "నమోదైన మొబైల్ నంబర్ (ధృవీకరణ కోసం)",
    "WhatsApp number set nahi hai — email se bhej do": "WhatsApp నంబర్ సెట్ కాలేదు — ఇమెయిల్ ద్వారా పంపండి",
    "aur print aapke printer se KHUD nikal jata hai.": "మరియు ప్రింట్ మీ ప్రింటర్ నుండి దానంతటదే వచ్చేస్తుంది.",
    "✅ Password changed — use it to log in next time": "✅ పాస్‌వర్డ్ మారింది — తర్వాతిసారి దీంతో లాగిన్ అవ్వండి",
    "3. Pehli baar khulte hi Shop ID poochega — daalo": "3. మొదటిసారి తెరిచినప్పుడే Shop ID అడుగుతుంది — పెట్టండి",
    "Agent purana hai — naya print agent install karo": "ఏజెంట్ పాతది — కొత్త print agent ఇన్‌స్టాల్ చేయండి",
    "Jaise: MS Office, Tally, Spoken English, Driving": "ఉదా: MS Office, Tally, స్పోకెన్ ఇంగ్లీష్, డ్రైవింగ్",
