    "Password bhool gaye ya pehli baar set karna hai?": "పాస్‌వర్డ్ మర్చిపోయారా, లేదా మొదటిసారి సెట్ చేయాలా?",
    "me unlock karein? Ek baar ka payment — lifetime.": "కు అన్‌లాక్ చేయాలా? ఒకసారి చెల్లింపు — లైఫ్‌టైమ్.",
    "— Cyber Cafe & Print Shop ka Auto Print Software": "— సైబర్ కేఫ్ & ప్రింట్ షాప్ కోసం ఆటో ప్రింట్ సాఫ్ట్‌వేర్",
    "Demo khatam hote hi print nikalna band ho jayega.": "డెమో ముగిసిన వెంటనే ప్రింట్ రావడం ఆగిపోతుంది.",
    "Koi bhi dikkat ho — seedhe WhatsApp par baat karo": "ఏ ఇబ్బంది ఉన్నా — నేరుగా WhatsApp లో మాట్లాడండి",
    "Niche button se Cashfree Merchant Dashboard kholo": "కింది బటన్‌తో Cashfree Merchant Dashboard తెరవండి",
