    "⚠️ Network issue — 2 min me khud unlock ho jayega": "⚠️ నెట్‌వర్క్ సమస్య — 2 నిమిషాల్లో దానంతటదే అన్‌లాక్ అవుతుంది",
    "⚫ Dual-Side sirf B&W par dikhega — Color par nahi": "⚫ డ్యుయల్-సైడ్ బ్లాక్&వైట్‌లో మాత్రమే కనిపిస్తుంది — కలర్‌లో కాదు",
    "✅ Supabase (naya database) me abhi itna data hai:": "✅ Supabase (కొత్త డేటాబేస్) లో ప్రస్తుతం ఇంత డేటా ఉంది:",
    "❌ Password 3 baar galat — dobara file upload karo": "❌ పాస్‌వర్డ్ 3 సార్లు తప్పు — మళ్లీ ఫైల్ అప్‌లోడ్ చేయండి",
    "🌈 Dual-Side sirf Color par dikhega — B&W par nahi": "🌈 డ్యుయల్-సైడ్ కలర్‌లో మాత్రమే కనిపిస్తుంది — బ్లాక్&వైట్‌లో కాదు",
    "+ Add Qualification (DCA / ITI / Certificate etc.)": "+ అర్హత జోడించండి (DCA / ITI / సర్టిఫికెట్ మొదలైనవి)",
    "Business/Website URL puchhe to likho: qrseprint.in": "బిజినెస్/వెబ్‌సైట్ URL అడిగితే రాయండి: qrseprint.in",
    "Earn lifetime by becoming an agent in QR Se Print.": "QR Se Print లో ఏజెంట్ అయి జీవితాంతం సంపాదించండి.",
    "Logo %d KB se chhota hona chahiye (abhi %d KB hai)": "లోగో %d KB కంటే చిన్నదిగా ఉండాలి (ప్రస్తుతం %d KB ఉంది)",
    "Payment reference/ID daalo (Razorpay dashboard se)": "చెల్లింపు రిఫరెన్స్/ID పెట్టండి (Razorpay dashboard నుండి)",
    "Poora A4 document — marksheet, certificate, letter": "పూర్తి A4 డాక్యుమెంట్ — మార్క్‌షీట్, సర్టిఫికెట్, లేఖ",
    "Thodi roshni me ya khidki ke paas dobara photo lo.": "కొంచెం వెలుతురులో లేదా కిటికీ దగ్గర మళ్లీ ఫోటో తీయండి.",
    "✅ Data copy ho gaya! Neeche dekho kitne rows aaye:": "✅ డేటా కాపీ అయింది! కింద చూడండి ఎన్ని రోలు వచ్చాయి:",
    "🔁 Auto Duplex — printer khud dono side chhapta hai": "🔁 ఆటో డుప్లెక్స్ — ప్రింటరే రెండు వైపులా ముద్రిస్తుంది",
    "4×6 Photo · Resume · A3/A2/A1 · Duplex · Mini Print": "4×6 ఫోటో · రెజ్యూమ్ · A3/A2/A1 · డుప్లెక్స్ · మినీ ప్రింట్",
