    "Sirf PNG file chalegi (transparent background wali)": "PNG ఫైల్ మాత్రమే పని చేస్తుంది (ట్రాన్స్‌పేరెంట్ బ్యాక్‌గ్రౌండ్ ఉన్నది)",
    "dabao peeche bhi chhapa ho to neeche se add kar lo.": "నొక్కండి — వెనుక వైపు కూడా ముద్రించి ఉంటే కింద నుండి జోడించుకోండి.",
