    "Hello, %s Support 🙏%0A%0AShop ID: %s%0A%0AProblem: %s": "నమస్తే, %s సపోర్ట్ 🙏%0A%0AShop ID: %s%0A%0Aసమస్య: %s",
    "Lifetime access — No renewal, koi monthly charge nahi": "లైఫ్‌టైమ్ యాక్సెస్ — రెన్యువల్ లేదు, నెలవారీ ఛార్జీ లేదు",
    "No shops yet. Share your link, or create one from the": "ఇప్పటివరకు షాపులు లేవు. మీ లింక్ షేర్ చేయండి, లేదా ఇక్కడి నుండి ఒకటి సృష్టించండి:",
    "Upar stream chunein — automatically fill ho jayega...": "పైన స్ట్రీమ్ ఎంచుకోండి — దానంతటదే నిండిపోతుంది...",
