    "\"Our Official Partner\" logos (QR Se Print's partners — untick to remove from your site)": "\"Our Official Partner\" లోగోలు (QR Se Print పార్ట్‌నర్లు — మీ సైట్ నుండి తీసేయడానికి టిక్ తీసేయండి)",
    "\"%s\" — renew this shop for +%d days? Enter the payment reference — if you took cash, type CASH.": "\"%s\" — ఈ షాప్‌ను +%d రోజులకు రెన్యూ చేయాలా? పేమెంట్ రిఫరెన్స్ ఇవ్వండి — నగదు తీసుకుంటే CASH అని రాయండి.",
    "Premium ke saare feature, ek baar ka paisa. Na saal ka renewal, na mahine ka — Lifetime access.": "ప్రీమియం ఫీచర్లన్నీ, ఒకసారి చెల్లింపు. వార్షిక రెన్యూవల్ లేదు, నెలవారీ లేదు — లైఫ్‌టైమ్ యాక్సెస్.",
    "Aaj ke bhi, kal ke bhi. Jo bhi naya advance feature banega, apne aap mil jayega — saal me bas ek baar renew.": "ఇప్పటివీ, రేపటివీ. కొత్త అడ్వాన్స్ ఫీచర్ ఏది వచ్చినా ఆటోమేటిక్‌గా వస్తుంది — సంవత్సరానికి ఒకసారి మాత్రమే రెన్యూ.",
    "You sell three plans. Each has a base price you cannot go below — everything above the base is your margin. Monthly and Yearly shops must renew (their renewal payment also comes to your gateway); Lifetime is paid once.": "మీరు మూడు ప్లాన్‌లు అమ్ముతారు. ప్రతిదానికీ బేస్ ధర ఉంది, దాని కంటే తక్కువకు వెళ్లలేరు — బేస్ కంటే పైన ఉన్నదంతా మీ మార్జిన్. నెలవారీ, వార్షిక షాపులు రెన్యూ చేయాలి (వాటి రెన్యూవల్ చెల్లింపు కూడా మీ గేట్‌వేకే వస్తుంది); లైఫ్‌టైమ్ ఒకసారి చెల్లింపు.",
    "Free demo se shuru karo. Phir Rs 99/month ka monthly plan, Rs 649/799/999 ke yearly plan (Starter/Pro/Premium), ya Rs 1999 one-time lifetime plan — ek baar do, hamesha chalao. Koi hidden charge nahi, koi per-print commission nahi.": "ఉచిత డెమోతో మొదలుపెట్టండి. తర్వాత నెలకు రూ.99 నెలవారీ ప్లాన్, రూ.649/799/999 వార్షిక ప్లాన్‌లు (స్టార్టర్/ప్రో/ప్రీమియం), లేదా రూ.1999 ఒకసారి చెల్లించే లైఫ్‌టైమ్ ప్లాన్ — ఒకసారి ఇవ్వండి, ఎప్పటికీ నడపండి. దాచిన ఛార్జీలు లేవు, ప్రింట్‌కు కమీషన్ లేదు.",
    "There is a free demo first. After that plans start at ₹99 per month; yearly plans are ₹649 (Starter), ₹799 (Pro) and ₹999 (Premium); and there is a ₹1999 one-time Lifetime plan. There is no per-print commission and no hidden charge.": "ముందుగా ఉచిత డెమో ఉంది. ఆ తర్వాత ప్లాన్‌లు నెలకు ₹99 నుండి మొదలవుతాయి; వార్షిక ప్లాన్‌లు ₹649 (స్టార్టర్), ₹799 (ప్రో), ₹999 (ప్రీమియం); అలాగే ₹1999 ఒకసారి చెల్లించే లైఫ్‌టైమ్ ప్లాన్ ఉంది. ప్రింట్‌కు కమీషన్ లేదు, దాచిన ఛార్జీలు లేవు.",
    "Paid plans published on qrseprint.in include a monthly plan, yearly plans and a one-time lifetime plan. Monthly and yearly plans must be renewed to keep the service active; a lifetime plan needs no renewal. On purchase you get a limited, non-transferable licence to install and run the QR Se Print agent at your own shop. You may not:": "qrseprint.in లో ప్రచురించిన చెల్లింపు ప్లాన్‌లలో నెలవారీ ప్లాన్, వార్షిక ప్లాన్‌లు మరియు ఒకసారి చెల్లించే లైఫ్‌టైమ్ ప్లాన్ ఉన్నాయి. సేవ యాక్టివ్‌గా ఉండాలంటే నెలవారీ, వార్షిక ప్లాన్‌లను రెన్యూ చేయాలి; లైఫ్‌టైమ్ ప్లాన్‌కు రెన్యూవల్ అవసరం లేదు. కొనుగోలుపై మీ సొంత షాపులో QR Se Print ఏజెంట్‌ను ఇన్‌స్టాల్ చేసి నడపడానికి పరిమిత, బదిలీ చేయలేని లైసెన్స్ లభిస్తుంది. మీరు చేయకూడనివి:"
