    "Every motherboard looks a little different. Find the line that matches yours.": "ప్రతి motherboard కొంచెం భిన్నంగా ఉంటుంది. మీదానికి సరిపోయే లైన్ కనుగొనండి.",
    "Registered! Download the software below and message us for your demo Serial Key.": "రిజిస్టర్ అయ్యింది! కింద సాఫ్ట్‌వేర్ డౌన్‌లోడ్ చేసి, డెమో సీరియల్ కీ కోసం మాకు మెసేజ్ చేయండి.",
    "You will need them the first time you open the software. One serial key works on": "సాఫ్ట్‌వేర్ మొదటిసారి తెరిచినప్పుడు ఇవి కావాలి. ఒక serial key",
    "On your phone: WhatsApp → Settings → Linked Devices → Link a Device → scan the QR.": "మీ ఫోన్‌లో: WhatsApp → Settings → Linked Devices → Link a Device → QR స్కాన్ చేయండి.",
