    "A download link, plus your Serial Key and Shop ID. You can save them as a text file — keep it safe.": "డౌన్‌లోడ్ లింక్, మీ Serial Key మరియు Shop ID. వాటిని text file గా సేవ్ చేయవచ్చు — జాగ్రత్తగా ఉంచుకోండి.",
    "Windows needs two features switched on. Download the file below and double-click it — it does everything for you. Say": "Windows లో రెండు ఫీచర్లు ఆన్ చేయాలి. కింద ఉన్న ఫైల్ డౌన్‌లోడ్ చేసి డబుల్-క్లిక్ చేయండి — అదే అంతా చేస్తుంది. Windows పర్మిషన్ బాక్స్‌లో",
    "After that, if you want to continue, do not uninstall — the payment link is starting soon. You can then pay and get a Serial Key for one year.": "ఆ తర్వాత కొనసాగించాలంటే అన్‌ఇన్‌స్టాల్ చేయకండి — పేమెంట్ లింక్ త్వరలో మొదలవుతుంది. అప్పుడు చెల్లించి ఒక సంవత్సరానికి సీరియల్ కీ పొందవచ్చు.",
    "🔒 Your customers' files are printed on your own computer only. Nothing is uploaded to any server, and every file is deleted automatically as soon as the print is done.": "🔒 మీ కస్టమర్ల ఫైళ్లు మీ సొంత కంప్యూటర్‌లో మాత్రమే ప్రింట్ అవుతాయి. ఏ server కూ ఏమీ అప్‌లోడ్ కాదు, ప్రింట్ అవ్వగానే ప్రతి ఫైల్ ఆటోమేటిక్‌గా డిలీట్ అవుతుంది.",
    "Testing Demo is for 2 days. After that, if you want to continue, do not uninstall — the payment link is starting soon. You can then pay and get a Serial Key for one year.": "టెస్టింగ్ డెమో 2 రోజులకు. ఆ తర్వాత కొనసాగించాలంటే అన్‌ఇన్‌స్టాల్ చేయకండి — పేమెంట్ లింక్ త్వరలో మొదలవుతుంది. అప్పుడు చెల్లించి ఒక సంవత్సరానికి సీరియల్ కీ పొందవచ్చు."
